package lt.benas.wispbound;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.webkit.*;import android.view.View;import org.json.JSONObject;import java.io.*;
public class MainActivity extends Activity {
 static final String LOCAL="https://wispbound.local/";static MainActivity instance;WebView web;volatile boolean runActive=false;private String exportData;private ValueCallback<Uri[]> fileCallback;
 @Override public void onCreate(Bundle state){super.onCreate(state);instance=this;getWindow().setStatusBarColor(0xff102a30);getWindow().setNavigationBarColor(0xff102a30);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);web.addJavascriptInterface(new Bridge(),"WispboundNative");
  web.setWebViewClient(new WebViewClient(){
   @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){Uri uri=req.getUrl();if(!"https".equals(uri.getScheme())||!"wispbound.local".equals(uri.getHost()))return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",null,new ByteArrayInputStream(new byte[0]));String path=uri.getPath();if(path==null||path.equals("/"))path="/index.html";if(path.contains("..")||path.contains("\\"))return new WebResourceResponse("text/plain","UTF-8",null);try{String mime=path.endsWith(".js")?"text/javascript":path.endsWith(".css")?"text/css":path.endsWith(".png")?"image/png":path.endsWith(".svg")?"image/svg+xml":path.endsWith(".wav")?"audio/wav":path.endsWith(".mp3")?"audio/mpeg":path.endsWith(".json")?"application/json":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open("web"+path));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(r.isForMainFrame()&&"https".equals(u.getScheme())&&("wispbound.local".equals(u.getHost())||Uri.parse(Updater.ORIGIN).getHost().equals(u.getHost()))){if(u.getPath().endsWith(".apk")){openPublic();return true;}if("wispbound.local".equals(u.getHost()))return false;}return true;}
  });
  web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,23);return true;}catch(Exception e){fileCallback.onReceiveValue(null);fileCallback=null;return false;}}});web.loadUrl(LOCAL);
 }
 void openPublic(){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(Updater.ORIGIN+"/#download")));}catch(Exception ignored){}}
 class Bridge{
  @JavascriptInterface public void setRunActive(boolean active){runActive=active;}
  @JavascriptInterface public void checkUpdate(){Updater.check(MainActivity.this);}
  @JavascriptInterface public void downloadUpdate(){if(!runActive)Updater.download(MainActivity.this);else Updater.set("active",-1);}
  @JavascriptInterface public void installUpdate(){runOnUiThread(()->{if(!runActive)Updater.install(MainActivity.this);else Updater.set("active",-1);});}
  @JavascriptInterface public void exportSave(String json){if(json==null||json.length()>5000000)return;exportData=json;runOnUiThread(()->{try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"wispbound-save.json"),22);}catch(Exception ignored){exportData=null;}});}
 }
 static void update(String json){MainActivity a=instance;if(a!=null&&a.web!=null)a.runOnUiThread(()->a.web.evaluateJavascript("window.onNativeUpdate&&window.onNativeUpdate("+json+")",null));}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==23&&fileCallback!=null){fileCallback.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);fileCallback=null;}if(req==22&&exportData!=null){if(result==RESULT_OK&&data!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(exportData.getBytes("UTF-8"));}catch(Exception ignored){}exportData=null;}}
 @Override protected void onPause(){super.onPause();if(web!=null){web.evaluateJavascript("window.onNativePause&&window.onNativePause()",null);web.onPause();}}
 @Override protected void onResume(){super.onResume();if(web!=null){web.onResume();web.evaluateJavascript("window.onNativeResume&&window.onNativeResume()",null);}Updater.resume(this);}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const c=document.querySelector('#skill-popup[open] [data-action=closeskill]')||document.querySelector('dialog[open] [data-action=close]');if(c)c.click();else document.querySelector('#run-actions [data-action=pause]')?.click();})()",null);}
 @Override protected void onDestroy(){if(instance==this)instance=null;if(web!=null){web.removeJavascriptInterface("WispboundNative");web.destroy();web=null;}super.onDestroy();}
}
